problems.solutionCode:
#include <iostream>
#include <string>

struct Unit {
    std::string name;
    int hp = 100;
    int attack = 30;
    int armor = 10;
};

// (1) Read-only, always present -> reference to const.
//     Accepts const units and temporaries, and cannot modify either argument.
int ComputeDamage(const Unit& attacker, const Unit& defender) {
    const int damage = attacker.attack - defender.armor;
    return damage > 0 ? damage : 0;
}

// (2) Modifies the caller's object, always present -> reference to non-const.
void ApplyDamage(Unit& target, int amount) {
    target.hp -= amount;
    if (target.hp < 0) target.hp = 0;
}

// (3) "No ally" is a valid input -> pointer, and nullptr is checked before use.
bool HealAlly(Unit* ally, int amount) {
    if (ally == nullptr) return false;
    ally->hp += amount;
    return true;
}

// (4) The target must be re-pointed later -> store a pointer.
//     A reference member can never be made to refer to another object:
//     `target_ = next` would copy `next` INTO the unit it was bound to.
class TargetLock {
public:
    explicit TargetLock(Unit& first) : target_(&first) {}
    void Retarget(Unit& next) { target_ = &next; }
    const Unit& Current() const { return *target_; }

private:
    Unit* target_;  // non-owning, never null (set from references only)
};

int main() {
    Unit knight{"Knight", 100, 30, 10};
    Unit orc{"Orc", 80, 25, 5};
    Unit bat{"Bat", 20, 10, 0};

    ApplyDamage(orc, ComputeDamage(knight, orc));
    std::cout << "orc hp: " << orc.hp << " (expected 55)\n";

    const Unit dummy{"Training Dummy", 1, 0, 0};
    std::cout << "vs dummy: " << ComputeDamage(knight, dummy) << " (expected 30)\n";

    std::cout << "healed: " << HealAlly(nullptr, 10) << " (expected 0)\n";
    const bool healed = HealAlly(&knight, 10);
    std::cout << "healed: " << healed << ", knight hp: " << knight.hp << " (expected 1, 110)\n";

    TargetLock lock(orc);
    lock.Retarget(bat);
    std::cout << "locked on: " << lock.Current().name << " (expected Bat)\n";
    std::cout << "orc is: " << orc.name << " with hp " << orc.hp << " (expected Orc with hp 55)\n";
    return 0;
}

